import { readFile } from "node:fs/promises";
import { extractAuthor, extractIssueIsbn, removeIsbnFromTitle, normalizeIsbn } from "./book-matching.mjs";
import { findBookByIsbn, findBookByTitle } from "./book-providers.mjs";
import { createGitHubClient, limitLabelLength } from "./github-issues.mjs";

const NO_COVER_IMAGE = "https://placehold.co/128x196?text=No+cover";

function getIssueBookDetails(issue) {
  const isbn = extractIssueIsbn(issue);
  return {
    isbn,
    title: removeIsbnFromTitle(issue.title || ""),
    author: extractAuthor(issue.body || ""),
  };
}

function createBookLabels(book, now = new Date()) {
  const slugify = (value) => value
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 40);

  const labels = [
    "kind: book",
    `started: ${now.toLocaleString("en", { month: "long", timeZone: "UTC" }).toLowerCase()}`,
    `started: ${now.getUTCFullYear()}`,
    ...book.authors.map((author) => `author: ${slugify(author)}`),
    ...book.categories.map((category) => `category: ${slugify(category)}`),
  ];

  if (book.publishedDate) {
    const year = Number(book.publishedDate.slice(0, 4));
    if (Number.isFinite(year) && year > 0) {
      labels.push(`year: ${year}`, `decade: ${Math.floor(year / 10) * 10}s`);
    }
  }

  if (book.language) labels.push(`language: ${slugify(book.language)}`);
  if (book.publisher) labels.push(`publisher: ${slugify(book.publisher)}`);
  return [...new Set(labels.map(limitLabelLength))];
}

function getMetadataSource(book, requestedIsbn) {
  if (requestedIsbn && [book.isbn10, book.isbn13].some(
    (isbn) => isbn && normalizeIsbn(isbn) === normalizeIsbn(requestedIsbn),
  )) {
    return "ISBN match";
  }

  return book.googleBooks?.id
    ? "Google Books title/author match"
    : "Open Library title/author match";
}

function createBookComment(book, { isbn, author }) {
  const sourceName = book.googleBooks?.id
    ? "Google Books"
    : book.googleBooks?.info?.includes("planetadelibros.com")
      ? "PlanetadeLibros"
      : "Open Library";
  const sourceUrl = book.googleBooks?.info || book.googleBooks?.canonical;
  const coverMissing = book.image === NO_COVER_IMAGE;
  const matchDescription = isbn
    ? `Matched using ISBN ${isbn}.`
    : `Matched using title${author ? " and author" : ""}; please verify the edition.`;

  const details = {
    ...book,
    ...(isbn ? { requestedIsbn: isbn } : {}),
    metadataSource: getMetadataSource(book, isbn),
  };

  return [
    "<!-- This comment is autogenerated by the Libros metadata resolver -->",
    "",
    `Book match: **${book.title}** by ${book.authors.join(", ") || "unknown author"}.`,
    matchDescription,
    coverMissing ? "No cover was found in the metadata providers; a neutral placeholder is used." : "",
    sourceUrl ? `Source: [${sourceName}](${sourceUrl}).` : "",
    "",
    "<details>",
    "<summary>Book details (JSON)</summary>",
    "",
    "```json",
    JSON.stringify(details, null, 2),
    "```",
    "",
    "</details>",
    "",
    "When you finish reading, close this issue to mark it as completed. 👍",
  ].filter(Boolean).join("\n");
}

async function commentAndFail(github, issueNumber, message) {
  await github.addComment(issueNumber, message);
  throw new Error(message);
}

async function resolveBook({ isbn, title, author }, github, issueNumber) {
  if (isbn) {
    const book = await findBookByIsbn(isbn);
    if (book) return book;

    await commentAndFail(
      github,
      issueNumber,
      `I couldn't find an exact edition for ISBN ${isbn} in Google Books, Open Library, or the Spanish publisher catalog. I haven't selected a different edition or guessed a cover. Check the ISBN or add the book details manually, then create a new issue to retry.`,
    );
  }

  const book = await findBookByTitle(title, author);
  if (book) return book;

  await commentAndFail(
    github,
    issueNumber,
    `I couldn't find a sufficiently reliable match for "${title}"${author ? ` by ${author}` : ""}. Add the ISBN to the issue title or body, or add an "Author: Name" line to the body, then create a new issue to retry.`,
  );
}

async function enrichIssue(issue, github) {
  const issueNumber = issue.number;
  const search = getIssueBookDetails(issue);

  if (!search.title && !search.isbn) {
    throw new Error("The issue title is empty after removing the ISBN.");
  }

  const book = await resolveBook(search, github, issueNumber);
  book.image ||= NO_COVER_IMAGE;

  await github.addComment(issueNumber, createBookComment(book, search));

  const resolvedTitle = book.authors.length
    ? `${book.title} by ${book.authors.join(", ")}`
    : book.title;
  if (resolvedTitle !== issue.title) {
    await github.updateIssueTitle(issueNumber, resolvedTitle);
  }

  const labels = createBookLabels(book);
  for (const label of labels) {
    await github.ensureLabel(label);
  }
  await github.addLabels(issueNumber, labels);
  await github.lockIssue(issueNumber);

  console.log(`Resolved issue #${issueNumber} to "${book.title}"${search.isbn ? ` using ISBN ${search.isbn}` : ""}`);
}

async function main() {
  const { GITHUB_TOKEN, GITHUB_EVENT_PATH, GITHUB_REPOSITORY } = process.env;
  if (!GITHUB_TOKEN || !GITHUB_EVENT_PATH || !GITHUB_REPOSITORY) {
    throw new Error("GITHUB_TOKEN, GITHUB_EVENT_PATH and GITHUB_REPOSITORY are required.");
  }

  const event = JSON.parse(await readFile(GITHUB_EVENT_PATH, "utf8"));
  if (!event.issue?.number) {
    throw new Error("This workflow did not receive an issue event.");
  }

  const github = createGitHubClient({ token: GITHUB_TOKEN, repository: GITHUB_REPOSITORY });
  await enrichIssue(event.issue, github);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
